function reverseBits(x) {
    x = x >>> 0;
    x = ((x & 0xffff0000) >>> 16) | ((x & 0x0000ffff) << 16);
    x = ((x & 0xff00ff00) >>> 8) | ((x & 0x00ff00ff) << 8);
    x = ((x & 0xf0f0f0f0) >>> 4) | ((x & 0x0f0f0f0f) << 4);
    x = ((x & 0xcccccccc) >>> 2) | ((x & 0x33333333) << 2);
    x = ((x & 0xaaaaaaaa) >>> 1) | ((x & 0x55555555) << 1);
    return x >>> 0;
}

function bitReverse(n, k) {
    return reverseBits(n) >>> (32 - k);
}

function modPow(a, p) {
    a = BigInt(a);
    if (p === 0) {
        return 1n;
    }
    const half = modPow(a, Math.floor(p / 2));
    let ans = (half * half) % MOD;
    if (p % 2 === 1) {
        ans = (ans * a) % MOD;
    }
    return ans;
}

function modInv(a) {
    return modPow(a, Number(MOD - 2n));
}

